// After HTTP Request to POST /webhook/booker
const booker = $input.first().json;
const merge = $('Merge Student + Slot').first().json;

// n8n may nest body on some versions — prefer top-level booker fields
const resultType = String(booker.resultType || booker.body?.resultType || 'OTHER_FAIL');
const message = String(booker.message || booker.body?.message || booker.detail || '');
const attempt = booker.attempt ?? booker.body?.attempt ?? null;

// Only real captcha exhaustion should trigger n8n "retry" path (optional)
const shouldRetry = resultType === 'CAPTCHA_FAIL' && booker.ok === false;

return [{
  json: {
    ...merge,
    ok: booker.ok === true,
    resultType,
    errorText: message || resultType,
    shouldRetry,
    bookerAttempt: attempt,
    captchaText: booker.captchaText || '',
    finalUrl: booker.finalUrl || '',
    timestamp: booker.timestamp || new Date().toISOString(),
    webhookResponse: {
      ok: booker.ok,
      resultType,
      attempt,
      message,
      artifacts: booker.artifacts || null,
    },
  },
}];

// Merge student data with current slot + session data
const student = $('Get Next PENDING Student').first().json;
const slotData = $('One Slot at a Time').first().json;

console.log(`Processing: Student ${student.Firstname} ${student.Lastname} | Slot: ${slotData.currentSlot}`);

return [{
  json: {
    ...slotData,
    student
  }
}];

// Split freshSlots into one item per slot for sequential processing
const data = $input.first().json;
const freshSlots = data.freshSlots || [];

return freshSlots.map((slot, index) => ({
  json: {
    ...data,
    currentSlot: slot,
    slotIndex: index
  }
}));

// The insert node returns DB rows, not our original data
// So we reach back to Prepare Slots for Insert to get _payload
const allItems = $('Prepare Slots for Insert').all();
if (!allItems.length) return [];

// All items share the same _payload — grab from first
const payload = allItems[0].json._payload;
if (!payload) throw new Error('_payload missing from Prepare Slots for Insert');

console.log(`Rebuilt payload with ${payload.freshSlots ? payload.freshSlots.length : 0} fresh slots`);
return [{ json: { ...payload } }];

// Explode freshSlots into one item per slot for bulk insert
const data = $input.first().json;
const freshSlots = data.freshSlots || [];
const now = new Date().toISOString();

return freshSlots.map(slot => ({
  json: {
    slotValue: slot,
    weekLabel: data.weekLabel || '',
    office: data.Office || 'KAIRO',
    calendarId: String(data.CalendarId || '44281520'),
    detectedAt: now,
    status: 'PENDING',
    assignedToStudentId: null,
    attemptedAt: null,
    result: '',
    _payload: data
  }
}));

// Get webhook payload
const payload = $('Webhook1').first().json.body || $('Webhook1').first().json;
const retryCount = payload.retryCount || 0;

// RETRY PATH: skip filtering, pass current slot directly
if (retryCount > 0) {
  console.log(`RETRY attempt #${retryCount} for slot: ${payload.currentSlot}`);
  return [{
    json: {
      ...payload,
      freshSlots: [payload.currentSlot],
      isRetry: true,
      retryCount
    }
  }];
}

// NORMAL PATH: filter slots against blacklist
const blacklistedSlots = $input.all().map(r => r.json.slotValue).filter(Boolean);
const foundSlots = payload.foundSlots || [];
const freshSlots = foundSlots.filter(s => !blacklistedSlots.includes(s));

console.log(`Slots received: ${foundSlots.length} | Blacklisted: ${blacklistedSlots.length} | Fresh: ${freshSlots.length}`);

return [{
  json: {
    ...payload,
    freshSlots,
    isRetry: false,
    retryCount: 0
  }
}];

